      '<footer class="foot">\n  <div class="foot-inner">\n    <div>© 2026 PaxLabs Inc. and the Paxeer Group. All rights reserved.</div>\n    <div class="links">\n      <a href="/legal">Legal Home</a>\n      <a href="/terms">Terms</a>\n      <a href="/privacy">Privacy</a>\n      <a href="/cookies">Cookies</a>\n      <a href="/risk-disclosure">Risk</a>\n    </div>\n  </div>\n</footer>',
